(window.TNQ=window.TNQ||[]).push({"terms":{"간이과세자":{"d":"직전 연도 공급대가 합계액이 일정 기준에 미달하는 개인사업자로, 부가가치율을 적용해 간편하게 세액을 계산한다.","r":[]},"일반과세자":{"d":"간이과세자가 아닌 과세사업자로 매출세액에서 매입세액을 공제해 납부세액을 계산합니다.","r":["간이과세자"]},"공급대가":{"d":"공급가액에 부가가치세를 더한 금액으로, 간이과세자의 과세 기준과 세액 계산에 쓰인다.","r":[]},"공급가액":{"d":"부가가치세 과세표준이 되는 공급 대가의 금액으로, 부가가치세 자체는 포함하지 않는다.","r":[]},"사업자 단위 과세":{"d":"사업장이 여럿인 사업자가 본점 한 곳에서 등록·신고·납부를 모두 처리하는 제도입니다.","r":["주사업장 총괄 납부"]},"주사업장 총괄 납부":{"d":"신고는 사업장별로 하되 납부만 주된 사업장에서 합쳐 처리하는 제도입니다.","r":["사업자 단위 과세"]},"영세율":{"d":"수출 등 외화 획득 거래의 공급에 0의 세율을 적용하여 매입세액을 환급받게 하는 제도이다.","r":[]},"면세포기":{"d":"면세 대상 사업자가 신고하여 면세를 포기하고 과세사업자가 되어 매입세액을 공제받는 것을 말한다.","r":[]},"상호주의":{"d":"외국인에게 주는 혜택을 그 나라도 우리 국민에게 주는 범위에서만 인정하는 원칙입니다.","r":[]},"공통매입세액":{"d":"과세사업과 면세사업을 겸영하는 사업자가 두 사업에 공통으로 사용하는 재화의 매입세액을 말한다.","r":[]},"의제매입세액":{"d":"면세농산물 등을 원재료로 쓴 사업자에게 매입세액이 있는 것으로 보아 일정 율로 공제해 주는 세액이다.","r":[]},"대손세액":{"d":"외상 대금을 받지 못해 대손이 확정되었을 때 매출세액에서 덜어 내는 부가가치세액입니다.","r":[]},"예정고지":{"d":"예정신고 대신 직전 납부세액의 일부를 세무서가 미리 고지해 납부하게 하는 제도입니다.","r":["예정신고"]},"예정신고":{"d":"부가가치세 과세기간 중 처음 3개월에 대해 미리 하는 신고와 납부이다.","r":[]},"조기환급":{"d":"영세율 적용, 사업설비 투자 등 일정한 경우에 환급세액을 일반 환급보다 앞당겨 돌려주는 제도이다.","r":[]},"조건부 면세":{"d":"정해진 용도에 사용하는 것을 조건으로 개별소비세를 면제하고, 조건을 어기면 면제한 세액을 징수하는 제도이다.","r":[]},"무조건 면세":{"d":"과세물품이 법에 정한 용도에 해당하면 조건 없이 개별소비세를 면제하는 것을 말한다.","r":[]},"알코올분":{"d":"전체 용량 중 에틸알코올이 차지하는 비율로, 주정의 세율 산정에 쓰인다.","r":[]},"조주정":{"d":"불순물이 있어 그대로 마실 수 없으나 정제하면 음용할 수 있는 알코올이다.","r":[]},"납세보증주류":{"d":"주세 보전을 위하여 관할 세무서장의 명령에 따라 주류 제조자가 담보로 보존하는 주류를 말한다.","r":[]},"인지세":{"d":"재산 관련 권리의 창설·이전·변경을 증명하는 문서를 만들 때 내는 세금입니다.","r":["전자수입인지","보완문서"]},"전자수입인지":{"d":"인지세를 내는 데 쓰는 전자 방식의 수입인지로 재사용하면 처벌받습니다.","r":["인지세"]},"보완문서":{"d":"다른 문서의 내용을 보충해 하나의 계약을 이루는 문서로 과세문서로 취급합니다.","r":["인지세"]},"공소시효":{"d":"범죄 후 일정 기간이 지나면 검사가 기소할 수 없게 하는 제도입니다.","r":[]},"가공거래":{"d":"재화나 용역의 실제 공급 없이 세금계산서만 주고받는 거래입니다.","r":[]},"미납세반출":{"d":"과세물품을 세금을 내지 않은 채 제조장이나 보세구역에서 반출하는 제도로, 정해진 사유와 승인이 있어야 한다.","r":[]},"과세표준":{"d":"세율을 곱하여 세액을 계산하는 기준이 되는 금액을 말한다.","r":[]},"과세물품":{"d":"개별소비세법에 열거되어 개별소비세가 부과되는 물품을 말한다.","r":[]},"과세장소":{"d":"입장행위에 대하여 개별소비세를 부과하는 경마장, 골프장 같은 장소를 말한다.","r":[]},"과세유흥장소":{"d":"유흥음식행위에 대하여 개별소비세를 부과하는 유흥주점 등의 영업장소를 말한다.","r":[]},"과세영업장소":{"d":"영업행위에 대하여 개별소비세를 부과하는 카지노 같은 영업장소를 말한다.","r":[]},"납세의무자":{"d":"세법에 따라 세금을 납부할 의무가 있는 자를 말한다.","r":[]},"반출가격":{"d":"과세물품을 제조장에서 반출할 때의 가격으로, 개별소비세 과세표준 계산의 기준이 된다.","r":[]},"보세구역":{"d":"관세법에 따라 수입신고 수리 전의 외국물품을 장치하거나 검사하는 지정된 장소를 말한다.","r":[]},"환입":{"d":"반출했던 물품을 제조장 등 원래의 장소로 다시 들여오는 것을 말한다.","r":[]},"재수출":{"d":"수입한 물품을 다시 외국으로 수출하는 것을 말한다.","r":[]},"통상가격":{"d":"납세 보증 주류의 가격을 판단할 때 기준이 되는, 통상 거래되는 가격을 말한다.","r":[]},"주정":{"d":"희석하여 음용할 수 있는 에틸알코올로, 주세법상 주류에 포함된다.","r":[]},"술덧":{"d":"당분이 있는 재료를 효모로 알코올 발효시킬 수 있도록 효모를 배양ㆍ증식한 것으로, 술의 원료가 된다.","r":[]},"밑술":{"d":"주류 제조에 쓰는 원료용 발효물로, 제조 면허의 대상이 되는 술덧과 함께 다뤄진다.","r":[]},"면세주류":{"d":"수출하는 것, 외국 군대에 납품하는 것 등 주세법에 따라 주세를 면제하는 주류를 말한다.","r":[]},"전통주":{"d":"주세법에서 무형유산 보유자가 제조하는 등 일정 요건을 갖춰 세율 등에서 특례를 받는 주류를 말한다.","r":[]},"종합주류도매업":{"d":"주류제조자나 수입자로부터 주정을 제외한 주류를 구입하여 도매하는 주류 판매업이다.","r":[]},"납세증명표지":{"d":"주류가 세금을 낸 것임을 표시하여 주류 용기에 붙이는 표지를 말한다.","r":[]},"공매":{"d":"국가가 압류하거나 보존 중인 재산을 경쟁 방식으로 팔아 세금에 충당하는 절차를 말한다.","r":[]},"재화의 공급":{"d":"계약상 원인에 따라 재화를 인도하거나 양도하는 것으로 부가가치세 과세대상이 된다.","r":[]},"용역의 공급":{"d":"계약상 원인에 따라 역무를 제공하거나 시설물, 권리를 사용하게 하는 것으로 부가가치세 과세대상이 된다.","r":[]},"재화의 수입":{"d":"외국에서 도착한 물품으로 수입신고가 수리되기 전의 것을 국내에 반입하는 것 등을 말한다.","r":[]},"공급시기":{"d":"재화나 용역의 공급이 이루어진 것으로 보는 때로, 세금계산서 발급시기의 기준이 된다.","r":[]},"공급장소":{"d":"재화나 용역의 공급이 국내인지 국외인지를 가르는 기준이 되는 장소를 말한다.","r":[]},"세금계산서":{"d":"사업자가 재화나 용역을 공급할 때 공급가액과 세액을 적어 발급하는 거래 증빙이다.","r":[]},"대손세액공제":{"d":"외상 매출금 등을 받지 못한 경우 그에 포함된 부가가치세액을 매출세액에서 공제하는 제도이다.","r":[]},"자기생산ㆍ취득재화":{"d":"사업자가 직접 생산하거나 취득한 재화로, 면세사업 전용 등 일정한 경우 재화의 공급으로 본다.","r":[]},"완성도기준지급조건부":{"d":"공사 진행 정도에 따라 대가를 받기로 한 조건의 거래로, 대가의 각 부분을 받기로 한 때가 공급시기가 된다.","r":[]},"중간지급조건부":{"d":"계약금을 받기로 한 날의 다음 날부터 재화 인도일까지 기간이 길고 대가를 나누어 받는 조건의 거래를 말한다.","r":[]},"장기할부판매":{"d":"재화를 공급하고 대가를 2회 이상 분할하여 받되 인도일 다음 날부터 최종 할부금 지급기일까지의 기간이 길게 정해진 판매이다.","r":[]},"위탁가공무역":{"d":"원자재를 외국의 수탁 사업자에게 보내 가공시킨 뒤 판매하는 무역 방식으로, 공급가액 산정에 특례가 있다.","r":[]},"내국신용장":{"d":"수출업자가 국내 공급업자에게 수출용 원자재 등을 공급받기 위해 은행이 개설해 주는 신용장이다.","r":[]},"수출재화임가공용역":{"d":"수출업자와 직접 도급계약을 맺어 수출 재화를 임가공하는 용역으로 영세율이 적용된다.","r":[]},"미가공식료품":{"d":"가공하지 않았거나 본래의 성질이 변하지 않는 정도로 1차 가공한 식료품으로 부가가치세가 면제된다.","r":[]},"국민주택규모":{"d":"주택법에서 정한 전용면적 기준의 주택 규모로, 이 이하의 공동주택 임대용역은 부가가치세가 면제된다.","r":[]},"봉사료":{"d":"개인서비스용역의 대가와 함께 받는 종업원의 봉사료로, 별도로 구분 기재하면 공급가액에 포함하지 않는다.","r":[]},"확정신고":{"d":"과세기간이 끝난 후 그 기간 전체의 과세표준과 납부세액 또는 환급세액을 신고하는 것이다.","r":[]},"경정":{"d":"과세관청이 이미 한 결정 또는 신고 내용에 오류가 있을 때 과세표준과 세액을 다시 정하는 것이다.","r":[]},"투전기":{"d":"돈을 넣고 승패에 따라 금품이 오가는 오락용 사행기구로, 개별소비세 과세물품이다.","r":[]},"가산세":{"d":"세법상 의무를 이행하지 않은 경우 본래의 세액에 더하여 징수하는 세금상의 제재를 말한다.","r":[]},"필요적 기재사항":{"d":"세금계산서에 반드시 적어야 하는 공급자 등록번호, 공급가액 등의 사항으로, 빠지면 가산세와 매입세액 불공제가 문제된다.","r":[]},"임의적 기재사항":{"d":"세금계산서에 적지 않아도 효력에 영향이 없는, 당사자가 필요에 따라 적는 사항을 말한다.","r":[]},"조기환급기간":{"d":"조기환급을 신청하기 위해 환급세액을 계산하는 대상이 되는 기간으로, 신고도 이 기간을 단위로 한다.","r":[]},"추계":{"d":"장부나 증명 자료가 없을 때 과세표준을 직접 증명하지 못하고 간접 자료로 추정하여 계산하는 것을 말한다.","r":[]},"부가가치율":{"d":"간이과세자의 납부세액 계산에서 업종별로 공급대가에 곱하는 율을 말한다.","r":[]},"실지귀속":{"d":"과세사업과 면세사업에 관련된 매입세액을 실제 어느 사업에 쓰였는지에 따라 구분하는 방식이다.","r":[]},"안분":{"d":"공통매입세액 등을 일정한 비율로 나누어 과세사업분과 면세사업분으로 배분하는 것을 말한다.","r":[]},"면세농산물":{"d":"부가가치세가 면제되는 농산물로, 이를 원재료로 쓰면 의제매입세액 공제를 받을 수 있다.","r":[]},"겸영":{"d":"한 사업자가 과세사업과 면세사업 등 둘 이상의 사업을 함께 경영하는 것을 말한다.","r":[]},"매출세액":{"d":"공급가액에 세율을 곱하여 계산한, 사업자가 거래 상대방으로부터 받는 부가가치세액이다.","r":[]},"매입세액":{"d":"사업자가 재화나 용역을 공급받을 때 부담한 부가가치세액으로, 원칙적으로 매출세액에서 공제한다.","r":[]},"납부세액":{"d":"매출세액에서 매입세액을 공제하는 등으로 계산한, 사업자가 납부해야 할 부가가치세액이다.","r":[]},"환급세액":{"d":"매입세액이 매출세액을 초과하는 등의 경우에 사업자가 돌려받는 부가가치세액이다.","r":[]},"대리납부":{"d":"국내사업장이 없는 비거주자 등으로부터 용역이나 권리를 공급받는 자가 대가를 지급할 때 세액을 징수해 대신 납부하는 제도이다.","r":[]},"납부유예":{"d":"중소ㆍ중견사업자가 재화를 수입할 때 부가가치세 납부를 정해진 기간 동안 미뤄 주는 제도이다.","r":[]},"수입세금계산서":{"d":"재화를 수입할 때 세관장이 수입하는 자에게 발급하는 세금계산서로, 관세의 과세표준과 관세액을 적는다.","r":[]},"전자세금계산서":{"d":"전자적 방법으로 발급하고 발급명세를 국세청장에게 전송하는 세금계산서로, 일정한 사업자는 의무적으로 발급해야 한다.","r":[]},"매입자발행세금계산서":{"d":"공급자가 세금계산서를 발급하지 않을 때 공급받는 자가 거래사실 확인을 받아 직접 발행하는 세금계산서이다.","r":[]},"세금계산서합계표":{"d":"사업자가 발급하거나 발급받은 세금계산서를 거래처별로 모아 신고 때 제출하는 서류이다.","r":[]},"실지거래가액":{"d":"토지와 건물 등을 함께 공급할 때 계약서에 구분된, 실제 거래에서 정한 가액을 말한다.","r":[]},"결제대행업체":{"d":"재화나 용역의 공급과 관련하여 결제를 대신 처리해 주는 업체로, 거래명세를 세무서장에게 제출해야 한다.","r":[]},"신용카드매출전표":{"d":"신용카드로 결제한 거래를 증명하는 전표로, 세금계산서 발급을 갈음하는 경우가 있다.","r":[]},"영수증":{"d":"최종 소비자와의 거래 등에서 공급받는 자의 등록번호와 부가가치세액을 구분하지 않고 발급하는 거래 증빙이다.","r":[]},"사업자등록":{"d":"사업자가 사업장마다 사업 개시일부터 일정 기간 내에 관할 세무서장에게 사업 사실을 등록하는 절차이다.","r":[]},"사업의 양도":{"d":"사업장 전체의 권리와 의무를 포괄적으로 넘기는 것으로, 재화의 공급으로 보지 않는다.","r":[]},"포탈":{"d":"사기나 그 밖의 부정한 행위로 세금을 내지 않거나 덜 내는 것을 말한다.","r":[]},"수정신고":{"d":"이미 신고한 과세표준이나 세액이 적게 신고된 경우에 납세자가 바로잡아 다시 하는 신고이다.","r":[]},"경정청구":{"d":"이미 신고한 과세표준이나 세액이 과다한 경우에 납세자가 관할 세무서장에게 감액을 요구하는 청구이다.","r":[]},"예정신고기간":{"d":"부가가치세 과세기간을 나눈 앞의 3개월로, 이 기간의 과세표준과 납부세액을 미리 신고ㆍ납부한다.","r":[]},"장부기록의무":{"d":"사업자가 거래내용을 장부에 기록하고 증빙과 함께 보존해야 하는 의무를 말한다.","r":[]},"시설대여업자":{"d":"여신전문금융업법에 따라 등록하고 사업설비 등을 빌려 주는 업자로, 이용자는 조기환급 요건과 관련된다.","r":[]},"지방소비세":{"d":"부가가치세액의 일부를 재원으로 지방자치단체에 배분하는 지방세이다.","r":[]},"과태료":{"d":"행정상 질서 위반에 대해 부과하는 금전적 제재로, 형벌이 아니라 행정질서벌이다.","r":[]},"면세사업":{"d":"부가가치세가 면제되는 재화나 용역을 공급하는 사업으로, 관련 매입세액은 공제되지 않는다.","r":[]}},"notes":{"100분의 30 범위에서 대통령령으로 조정할 수 있다":"탁주·맥주 세율은 정책 필요에 따라 100분의 30 범위에서 대통령령으로 조정할 수 있습니다.","1개당 200만원을 넘는 부분에 100분의 20을 매긴다":"고급 시계·융단·가방은 1개당 200만원을 넘는 부분에 100분의 20을 곱합니다.","1개당 500만원을 넘는 부분에 100분의 20을 매긴다":"보석·귀금속 제품과 고급 모피는 1개당 500만원을 넘는 부분에만 100분의 20이 붙습니다.","1년 이하의 징역 또는 공급가액에 부가가치세율을 곱한 세액의 2배 이하 벌금이다":"세금계산서를 발급하지 않거나 거짓으로 발급하면 1년 이하 징역 또는 부가가치세액의 2배 이하 벌금입니다.","1월 1일부터 12월 31일까지다":"간이과세자는 한 해 전체가 하나의 과세기간이라 신고 주기가 일반과세자보다 깁니다.","1월 1일부터 6월 30일까지가 간이과세자 과세기간이다":"간이과세자가 일반과세자로 바뀌는 해에는 앞의 반년만 간이과세자 기간으로 봅니다.","1월 1일부터 6월 30일까지가 제1기, 7월 1일부터 12월 31일까지가 제2기이다":"일반과세자는 한 해를 둘로 나눠 6월 30일까지를 제1기, 이후를 제2기로 신고합니다.","1조당 800만원 또는 1개당 500만원을 넘는 부분에 100분의 20을 매긴다":"고급 가구는 한 벌 기준이 1조당 800만원이고 낱개는 1개당 500만원이며 그 초과분에 100분의 20이 붙습니다.","1킬로리터당 5만 7천원이고 알코올분 95도를 넘는 1도마다 600원을 더한다":"주정은 1킬로리터당 정액을 매기고 알코올분이 95도를 넘으면 그 초과 도수 1도마다 600원이 추가됩니다.","1킬로리터당 88만5700원":"맥주의 세율은 1킬로리터당 88만5700원입니다.","2026년 1월 2일 폐지법률이 공포되었고, 폐지 시행 전까지는 이 법이 적용된다":"폐지법률이 이미 공포되었으나 폐지가 시행되기 전까지는 교통·에너지·환경세법이 계속 적용됩니다.","2년 이하 징역 또는 2천만원 이하 벌금":"남의 명의로 사업자등록을 하면 2년 이하 징역 또는 2천만원 이하 벌금에 처합니다.","2인 이상이 공동으로 작성하면 연대하여 납부한다":"2인 이상이 한 문서를 같이 작성하면 각자가 연대하여 인지세를 납부합니다.","3년 이하 징역 또는 3천만원(주세 상당액의 3배가 더 크면 그 금액) 이하 벌금":"무면허로 주류를 만들어 팔면 3년 이하 징역 또는 3천만원 이하 벌금이며 주세의 3배가 더 크면 그 금액입니다.","3년 이하 징역 또는 3천만원 이하 벌금":"체납처분을 피하려고 재산을 숨기는 행위는 3년 이하 징역 또는 3천만원 이하 벌금입니다.","3년 이하 징역 또는 5배 이하 벌금":"면세유를 부정하게 유통하면 3년 이하 징역 또는 5배 이하 벌금에 처합니다.","5만원 초과분부터 과세하며 7일 이내 전액 환불·폐기된 것은 제외한다":"모바일 상품권은 권면금액 중 5만원을 넘는 부분부터 과세하며 7일 안에 전액 환불·폐기하면 과세하지 않습니다.","5억원 이상(가산세 제외)이면 10년, 그 밖에는 5년간 행사하지 않으면 소멸한다":"국세징수권은 5억원 이상이면 10년, 그 밖에는 5년 동안 행사하지 않으면 소멸합니다.","7년이고, 행위자가 특정범죄가중법 제8조를 적용받으면 법인에 대한 공소시효는 10년이다":"조세범 처벌법의 공소시효는 7년이나 행위자에게 특정범죄가중법 제8조가 적용되면 법인은 10년입니다.","7월 1일부터 12월 31일까지가 간이과세자 과세기간이다":"반대로 일반과세자가 간이과세자로 바뀌면 7월부터 연말까지가 간이과세자 기간이 됩니다.","같은 제조장에서 과세물품의 원재료나 시험·연구·검사용으로 쓰는 것, 비과세 석유류의 원재료로 정유공정에 쓰는 것, 기업부설연구소로 옮겨 시험·연구에 쓰는 것, 납세 보증으로 보존하는 것":"같은 제조장 안에서 원재료나 시험·연구용으로 쓰는 경우는 소비자에게 간 것이 아니어서 반출로 보지 않습니다.","개시일부터 포기 신고일이 속하는 달의 마지막 날까지가 간이과세자, 그 다음 달 1일부터가 일반과세자 과세기간이다":"간이과세를 포기하면 신고일이 든 달 말일까지는 간이과세자이고 그 다음 달부터 일반과세자입니다.","개시일 전에도 신청할 수 있으며 다른 세무서장에게 신청해도 관할 세무서장에게 한 것으로 본다":"신규사업자는 개시 전에 신청해도 되고 다른 세무서장에게 냈더라도 관할 세무서장에게 낸 것으로 칩니다.","개인과 직전 과세기간 공급가액 1억5천만원 미만 법인은 직전 납부세액의 50퍼센트를 예정고지받는다":"개인과 규모가 작은 법인은 신고 대신 직전 납부세액의 50퍼센트를 예정고지로 먼저 냅니다.","개인이 6개월 이상 국외에 체류하려면 정한다":"납세관리인은 개인이 6개월 이상 국외에 머물러 세무를 직접 못 할 때 대신할 사람으로 정합니다.","거래의 전부 또는 일부를 하는 고정된 장소이고, 없으면 주소 또는 거소를 사업장으로 한다":"사업장은 거래를 하는 고정된 장소이며 그런 곳이 없을 때만 주소나 거소를 사업장으로 삼습니다.","거리·방법에 상관없이 같은 금액으로 받거나 낙찰가격에 운송비가 포함돼 있으면 운송비를 포함한다":"운송비를 거리와 무관하게 같은 금액으로 받거나 낙찰가격에 들어 있으면 과세표준에 포함합니다.","거리와 관계없이 같은 운송비를 받으면 운송비를 포함한다":"운송비를 거리에 상관없이 같은 액수로 받으면 반출 가격에 운송비를 포함시킵니다.","건당 5만원 이상 거래에 대해 과세기간 종료일부터 1년 이내에 확인을 신청한다":"매입자발행세금계산서는 공급자가 발급을 거부한 건당 5만원 이상 거래에 대해 1년 안에 확인을 신청합니다.","건물 등의 실지거래가액이 공급가액이고, 구분이 불분명하거나 안분액과 100분의 30 이상 차이 나면 감정평가가액, 기준시가, 장부가액 순으로 안분한다":"토지와 건물을 함께 공급하면 건물의 실지거래가액이 원칙이며 불분명하거나 차이가 크면 감정평가가액 등으로 안분합니다.","건설업자가 자재를 부담하는 건설, 주요자재를 전혀 부담하지 않는 단순 가공, 산업상·상업상·과학상 정보 제공":"건설업자가 자재를 대는 건설, 자재 없는 단순 가공, 정보 제공은 용역의 공급으로 봅니다.","경마장 1천원, 경륜·경정장 400원, 투전기 설치 장소 1만원, 골프장 1만2천원, 카지노 5만원(외국인 2천원)":"입장행위는 장소마다 정액이 달라 경마장 1천원, 골프장 1만2천원, 카지노 5만원이고 외국인 카지노는 2천원입니다.","계약금액을 통상가격으로 본다":"국군부대와 직접 계약했다면 계약금액을 통상가격으로 간주합니다.","고급 모피를 일시적으로 판매하는 소비자":"고급 모피를 한 번 팔았을 뿐인 소비자는 판매 사업자가 아니므로 개별소비세 납세의무자가 아닙니다.","고용관계에 따른 근로 제공은 용역의 공급이 아니고, 전·답·과수원·목장용지·임야·염전 임대업은 과세 용역에서 제외된다":"근로자가 고용관계로 일하는 것은 용역이 아니며 토지·임야 등의 임대업은 과세 용역에서 빠집니다.","공급과 직접 관련된 국고보조금·공공보조금":"공급과 직접 관련된 국고보조금과 공공보조금은 대가의 성격이 있어 공급가액에 넣습니다.","공급과 직접 관련 없는 보조금":"공급과 직접 관련이 없는 보조금은 대가가 아니므로 공급가액에 넣지 않습니다.","공급대가에 업종별 부가가치율과 10퍼센트를 곱하고, 공급대가 4천800만원 미만이면 납부의무를 면제한다":"간이과세자의 세액은 공급대가에 업종별 부가가치율과 10퍼센트를 곱해 구하고 4천800만원 미만이면 면제합니다.","공급받는 자에게 지급하는 장려금과 대손금은 공급가액에서 빼지 않는다":"장려금과 대손금은 이미 확정된 공급대가를 사후에 깎아 주는 것이 아니어서 공급가액에서 빼지 않습니다.","공급시기가 폐업일 후에 오면 폐업일이 공급시기다":"폐업일 뒤로 넘어갈 공급시기는 폐업일로 앞당겨 정합니다.","공급시기 전에 대가를 받고 세금계산서를 발급하거나, 발급 후 7일 이내에 대가를 받으면 발급한 때가 공급시기다":"공급시기 전에 대가를 받고 세금계산서를 내주거나 발급 후 7일 안에 받으면 발급 시점을 공급시기로 봅니다.","공급시기 후라도 확정신고기한까지 받은 세금계산서와 기재 착오가 있어도 거래사실이 확인되는 세금계산서는 공제한다":"공급시기가 지나도 확정신고기한까지 받은 세금계산서나 기재 착오가 있는 세금계산서는 거래사실이 확인되면 공제합니다.","공급이지만 사업자 단위 과세 사업자와 주사업장 총괄 납부 사업자는 제외하고, 총괄 납부 사업자가 세금계산서를 발급해 신고하면 공급으로 본다":"판매 목적으로 다른 사업장에 반출하면 원칙적으로 공급이고 총괄 납부 사업자는 세금계산서 발급 시 공급으로 봅니다.","공제하기 전 금액을 가격으로 한다":"상거래 관습상 깎아 주는 금액이 있더라도 깎기 전의 금액을 주류 가격으로 봅니다.","공제하지 않으며 예정신고 때도 공제한다":"면세를 포기하고 영세율을 적용할 때는 의제매입세액을 공제하지 않으며 예정신고 때도 공제합니다.","공제·환급은 사유 발생일부터 6개월이 지난 날이 속하는 달의 말일까지 신청하고 가산세는 공제·환급하지 않는다":"공제·환급은 사유 발생 후 6개월이 지난 날이 속한 달의 말일까지 신청하며 가산세는 돌려주지 않습니다.","과세기간 개시일부터 폐업일까지이고, 합병 소멸법인의 폐업일은 합병법인의 변경등기일 또는 설립등기일이다":"폐업하면 그 기간의 끝이 폐업일로 앞당겨지고 합병으로 사라진 법인은 합병법인의 등기일이 기준입니다.","과세기간이 끝나는 때, 수입재화는 세관장에게 수입신고를 하는 때 성립한다":"부가가치세 납세의무는 과세기간이 끝나는 때, 수입재화는 세관장에게 수입신고하는 때 성립합니다.","과세문서 작성일이 속하는 달의 다음 달 10일까지 납부하고, 전자조달시스템으로 작성하는 경우 등은 작성일에 납부한다":"납부기한은 작성일이 속한 달의 다음 달 10일이고 전자조달시스템 작성 등은 작성일에 냅니다.","과세물품을 제조해 반출하는 자, 보세구역에서 반출하는 자(관세 납세의무자), 과세장소·과세유흥장소·과세영업장소의 경영자다":"납세의무자는 과세물품을 제조해 내보내는 자, 보세구역에서 반출하는 자, 과세장소 경영자입니다.","과세물품을 제조해 반출하는 자, 보세구역에서 반출하는 자(관세 납세의무자), 그 밖에 관세를 징수하는 물품의 관세 납세의무자다":"납세의무자는 제조 후 반출하는 자, 보세구역 반출자, 관세를 징수하는 물품의 관세 납세의무자입니다.","과세사업에 전용하면 경과기간만큼 줄인 매입세액을 공제한다":"면세사업용이던 자산을 과세사업에 돌려쓰면 경과기간만큼 줄인 매입세액을 공제받습니다.","과세유흥장소를 폐업하면 폐업일이 속한 달의 다음 달 25일까지 신고·납부하고 외상매출금 잔액도 과세표준에 넣는다":"폐업해도 마지막 신고·납부 기한은 다음 달 25일이고 아직 받지 못한 외상매출금까지 과세표준에 넣습니다.","관세법에 따라 수입을 신고하는 세관의 소재지이고, 수입재화의 부가가치세는 세관장이 징수한다":"수입재화의 납세지는 수입신고를 하는 세관의 소재지이며 세관장이 직접 부가가치세를 거둡니다.","관세의 과세가격과 관세를 합한 금액(기준가격 초과분 과세 물품은 그 초과분)":"보세구역 반출 물품의 과세표준은 관세 과세가격과 관세의 합계이고 기준가격 초과분 과세 물품은 초과분입니다.","관세의 과세가격과 관세를 합한 금액이다":"수입 주류의 가격은 관세의 과세가격에 관세를 더한 금액으로 정합니다.","관세의 과세가격에 관세·개별소비세·주세·교육세·농어촌특별세·교통·에너지·환경세를 더한 금액이고 담배소비세는 넣지 않는다":"재화 수입의 공급가액은 관세 과세가격에 관세와 개별소비세 등을 더한 금액이고 담배소비세는 뺍니다.","관세의 과세가격이 매입가액이다":"수입 농산물에서는 관세의 과세가격을 매입가액으로 삼아 의제매입세액을 계산합니다.","관할 세무서장은 주세 보전을 위해 필요하면 주류 제조자에게 금액과 기간을 정해 담보를 제공하게 하거나 주세액에 상당하는 가액의 주류를 보존하도록 명할 수 있다":"세무서장은 주세를 보전하려고 주류 제조자에게 담보를 내게 하거나 주류를 보존하도록 명할 수 있습니다.","교통시설 확충과 대중교통 육성, 에너지·자원 사업, 환경 보전·개선 사업의 재원을 마련하기 위한 목적세다":"교통·에너지·환경세는 교통시설, 에너지·자원, 환경 사업의 재원을 대려고 걷는 목적세입니다.","국가 등과 그 밖의 자가 공동 작성해 각각 가지는 문서는 국가 등이 가진 것은 그 밖의 자가, 그 밖의 자가 가진 것은 국가 등이 작성한 것으로 본다":"국가 등과 그 밖의 자가 공동 작성한 문서는 상대방이 작성한 것으로 보아 국가 등이 가진 것은 그 밖의 자가 납세합니다.","국가·지방자치단체가 작성하는 증서, 국고금 취급 증서, 공공사업 기부 증서, 자선·구호단체의 사업 증서, 어음의 인수·보증, 우편전용 물건 증서, 공익사업용 토지를 국가 등에 양도하는 증서는 인지세를 내지 않는다":"국가 작성 증서, 국고금 취급 증서, 자선단체 증서, 어음 인수·보증 등은 비과세문서입니다.","국내에서 재산에 관한 권리의 창설·이전·변경에 관한 계약서나 이를 증명하는 문서를 작성하는 자가 인지세를 낸다":"인지세는 국내에서 재산 관련 권리의 창설·이전·변경 계약서 등 문서를 작성하는 사람이 냅니다.","국내에서 종교단체에 기증한 주류":"국내에서 종교단체에 기증하는 주류는 의식용 수입분과 달리 면세 대상이 아닙니다.","국외사업자의 전자적 용역은 공급받는 자의 사업장·주소지·거소지가 공급장소다":"국외사업자가 제공하는 전자적 용역은 이를 받는 사람의 사업장이나 주소지가 공급장소입니다.","권면금액 1만원 50원, 5만원 이하 200원, 10만원 이하 400원, 10만원 초과 800원":"상품권과 선불카드는 권면금액이 클수록 정액이 커져 1만원 50원부터 10만원 초과 800원까지 매깁니다.","그 반출가격을 주류 가격으로 한다":"외상으로 통상가격보다 높게 반출했다면 실제 반출가격을 주류의 가격으로 삼습니다.","금융기관과의 금전소비대차 증서, 법정 도급·위임 증서, 무체재산권 등 권리 양도 증서, 골프장·콘도 회원권 입회·양도 증서":"금융기관 금전소비대차, 법정 도급·위임, 무체재산권 양도, 골프장·콘도 회원권 증서는 소유권 이전 증서와 같은 세액표를 씁니다.","기본세율과 탄력세율에 우선한다":"잠정세율은 법에 정한 기본세율과 탄력세율보다 먼저 적용됩니다.","기재금액 1억원 이하 주택 소유권 이전 증서와 5천만원 이하 금전소비대차 증서도 비과세다":"서민 주거와 소액 대출을 배려해 1억원 이하 주택 이전 증서와 5천만원 이하 대차 증서는 인지세를 걷지 않습니다.","기재사항으로 계산하고, 계산할 수 없으면 최저 기재금액으로 본다":"기재금액이 없으면 기재사항으로 금액을 계산하고 계산이 안 되면 최저 기재금액으로 간주합니다.","납부만 총괄하고 신고·결정은 사업장별로 하며 법인은 본점 또는 지점, 개인은 주사무소를 주된 사업장으로 한다":"주사업장 총괄 납부는 세액 납부만 모아서 하고 신고와 결정은 사업장마다 따로 합니다.","납부세액의 100분의 20, 부정행위 무신고는 100분의 40이고, 과소신고는 100분의 10, 부정행위 과소신고는 100분의 40이다":"무신고는 납부세액의 100분의 20이고 부정행위를 하면 100분의 40이며 과소신고는 100분의 10 수준입니다.","납부하지 않았거나 부족하면 관할 세무서장이나 지방국세청장이 결정·경정한다":"인지세를 내지 않았거나 모자라면 관할 세무서장이나 지방국세청장이 결정·경정합니다.","납부한 뒤 문서를 작성하지 않으면 환급하거나 공제하고, 특허권·상표권 등 양도증서의 인지세는 지식재산처장이 징수해 납부한다":"이미 인지세를 냈는데 문서를 만들지 않았다면 환급하거나 공제하며 지식재산권 양도증서는 지식재산처장이 거둡니다.","다음 과세기간부터 사업장별로 신고·납부하거나 총괄 납부를 신청한다":"사업자 단위 과세를 포기하면 다음 과세기간부터 사업장별 신고·납부나 총괄 납부로 돌아갑니다.","다음 달 10일까지 발급할 수 있다":"한 달 거래분을 합쳐 쓰는 세금계산서는 다음 달 10일까지 발급해도 됩니다.","담보·보존 기간이 2주조연도 이상이면 매년 1월에 적정성을 조사한다":"담보나 보존이 오래 이어지는 2주조연도 이상의 경우에는 해마다 1월에 적정성을 따져 봅니다.","대가의 각 부분을 받기로 한 때이며, 중간지급조건부는 계약금 다음 날부터 인도일까지 6개월 이상인 경우다":"장기할부 등은 대가를 나누어 받기로 한 때마다 공급시기이며 중간지급조건부는 6개월 이상이어야 합니다.","대손금액의 110분의 10이고 공급일부터 10년이 지난 날이 속하는 과세기간의 확정신고기한까지 확정된 대손에 대해 확정신고 때만 공제한다":"대손세액은 대손금액의 110분의 10이며 시한 안에 확정된 대손만 확정신고 때 공제합니다.","대손세액공제와 의제매입세액공제가 없고, 세금계산서 수취세액공제(공급대가의 0.5퍼센트)는 환급하지 않는다":"간이과세자는 대손세액공제와 의제매입세액공제를 못 받으며 세금계산서 수취세액공제는 환급하지 않습니다.","둘 이상의 제조장이 있으면 사업자 단위로 본점에서 총괄 신고·납부할 수 있고, 사업자 단위 신고는 적용받으려는 달이 시작되기 20일 전까지 한다":"제조장이 둘 이상이면 본점에서 사업자 단위로 총괄 신고·납부할 수 있고 적용받을 달 20일 전까지 신고합니다.","등록 전이라도 공급시기가 속하는 과세기간이 끝난 후 20일 이내에 등록을 신청하면 그 과세기간 기산일까지 역산한 기간의 매입세액은 공제한다":"등록 전 매입세액은 과세기간이 끝난 후 20일 이내에 등록을 신청하면 그 기간 시작일까지 거슬러 공제받습니다.","매매·가공·교환·현물출자 등 계약상·법률상 원인에 따른 재화의 인도·양도가 재화의 공급이고, 특허권·저작권 같은 권리의 양도도 재화의 공급이다":"재화의 공급은 계약이나 법률상 원인으로 재화를 인도·양도하는 것이며 권리의 양도도 포함합니다.","매월 반출 물품의 수량·세액 등을 적은 신고서를 다음 달 말일까지 제조장 관할 세무서장에게 내고 그 기한 안에 납부한다":"제조 반출자는 매월 수량·세액을 적은 신고서를 다음 달 말일까지 제조장 관할 세무서장에게 내고 납부합니다.","매입세액이 공제된 자기생산·취득재화를 면세사업에 쓰거나, 개인적 목적으로 쓰거나, 고객에게 증여하거나, 폐업 때 남아 있으면 재화의 공급으로 본다":"공급의제는 대가 없이도 자기 재화를 면세사업에 쓰거나 증여하거나 폐업 때 남기면 공급으로 간주합니다.","면세공급가액이 5퍼센트 미만(공통매입세액 500만원 이상 제외), 공통매입세액 합계가 5만원 미만, 신규사업자가 그 과세기간에 매입·매각한 재화는 전부 공제한다":"면세 비중이 작거나 공통매입세액이 소액이거나 신규사업자의 당기 매입·매각분은 안분 없이 전부 공제합니다.","면세농산물을 원재료로 과세 재화를 공급하면 매입가액에 공제율을 곱해 공제한다":"의제매입세액공제는 면세농산물을 원재료로 과세 재화를 만들 때 매입가액에 공제율을 곱한 액수를 공제하는 제도입니다.","면세비율이 취득 또는 직전 재계산 과세기간보다 5퍼센트 이상 차이 나면 확정신고 때 재계산한다":"감가상각자산은 면세비율이 기준보다 5퍼센트 이상 달라지면 확정신고 때 매입세액을 다시 계산합니다.","명칭과 관계없이 실질적인 내용에 따라 판단하고 전자문서도 포함하며 통장은 1권마다, 그 밖의 문서는 1통마다 납부한다":"과세문서는 문서 이름이 아닌 실질 내용으로 판단하며 전자문서도 포함하고 통장은 1권, 그 밖은 1통마다 냅니다.","명칭과 관계없이 형태·용도·성질에 따르며 분해·미조립 상태로 반출해도 완제품으로 본다":"과세물품 여부는 이름이 아니라 형태·용도·성질로 판단하며 분해 상태로 내보내도 완제품으로 봅니다.","무도학원·자동차운전학원 교육, 은행업 소프트웨어 판매, 소포 방문접수 배달, 삭도·시외우등고속버스 운송, 골동품은 과세다":"무도학원 교육, 자동차운전학원 교육, 골동품 등은 면세 항목과 비슷해 보여도 과세 대상입니다.","무형유산 보유자가 판매 목적으로 만든 주류":"무형유산 보유자가 판매 목적으로 만든 술은 공개 행사용과 달리 면세가 되지 않습니다.","물품가격의 100분의 20이다":"투전기·오락용 사행기구와 수렵용 총포류의 세율은 물품가격의 100분의 20입니다.","미가공식료품(단순 혼합 포함), 토지, 도서·정기간행물(광고 제외), 우표(수집용 제외), 주택 임대(규모 무관), 의료보건 용역(안마사·장의·산후조리원 포함, 비급여 탈모치료술 제외), 인가 학교·산학협력단 교육, 시내버스 운송은 면세다":"면세는 가공하지 않은 식료품, 토지, 도서, 주택 임대, 의료보건 용역, 시내버스 운송 등 생활 필수적인 항목에 줍니다.","미납세액에 경과일수와 이자율을 곱한 금액과 지정납부기한까지 내지 않은 세액의 100분의 3을 더하며 인지세에는 이 규정을 적용하지 않는다":"납부지연가산세는 미납세액에 경과일수와 이자율을 곱하고 지정기한까지 못 낸 세액의 100분의 3을 더하며 인지세는 제외입니다.","미등록 가산세는 사업 개시일부터 등록 신청일 직전일까지 공급가액의 1퍼센트, 지연발급과 기재 착오는 1퍼센트, 미발급과 타인 명의 발급·수취는 2퍼센트, 가공 세금계산서는 3퍼센트, 전자발급명세 지연전송은 0.3퍼센트다":"가산세는 미등록·지연발급 1퍼센트, 미발급·타인 명의 2퍼센트, 가공 3퍼센트, 지연전송 0.3퍼센트로 위반 정도에 따라 다릅니다.","반입 사실을 증명하지 못하거나 용도 외로 쓰면 징수한다":"조건부 면세 물품은 반입을 증명하지 못하거나 용도 외로 쓰면 면제가 취소되어 징수합니다.","반출로 보는 경우는 사유가 생긴 달의 다음 달 말일까지 신고한다":"반출로 간주된 경우에는 사유가 생긴 달의 다음 달 말일까지 신고하며 보존명령 불이행도 같습니다.","반출자나 수입신고인에게서 징수하고, 반입 전 재해로 멸실되면 징수하지 않는다":"반입 사실을 증명하지 못하면 반출자나 수입신고인에게서 걷지만 반입 전에 재해로 없어졌다면 걷지 않습니다.","반출하거나 수입신고하는 때의 수량이고, 휘발유는 수송·저장 중 자연감소분을 뺀 수량으로 한다":"과세표준은 반출·수입신고 때의 수량이며 휘발유는 수송·저장 중 자연감소분을 뺍니다.","반출하는 때의 가격이나 수입신고를 하는 때의 가격이다":"그 밖의 주류는 수량이 아니라 반출 때나 수입신고 때의 가격이 과세표준입니다.","반출한 수량이나 수입신고하는 수량이 과세표준이다":"주정·탁주·맥주는 가격이 아니라 반출한 수량이나 수입신고한 수량이 과세표준입니다.","반출한 자는 매 분기 반출한 날이 속하는 분기의 다음 달 25일까지 신고한다":"반출자는 분기별로 반출한 날이 속한 분기의 다음 달 25일까지 주세를 신고합니다.","법인과 직전 연도 공급가액(면세 포함) 8천만원 이상 개인은 발급하고 발급일의 다음 날까지 국세청장에게 전송한다":"법인과 공급가액 8천만원 이상 개인은 전자세금계산서를 발급하고 발급 다음 날까지 국세청장에게 보냅니다.","법인의 대표자·종업원이 업무에 관해 범칙행위를 하면 행위자와 법인 모두 처벌한다":"법인의 대표자나 종업원이 업무상 범칙행위를 하면 행위자와 법인을 모두 처벌하는 양벌 규정입니다.","변질·품질불량으로 같은 제조자의 제조장에 다시 들어오거나 유통 중 파손·멸실되면 세액을 공제하거나 환급한다":"제조장에 다시 들어온 변질·불량 주류나 유통 중 파손·멸실된 주류는 세액을 공제하거나 환급합니다.","보존 주류의 가격은 통상가격이고, 제조자는 납세보증주류를 처분하거나 반출하지 못한다":"보존 주류는 통상가격으로 평가하며 제조자는 납세보증주류를 마음대로 팔거나 내보내지 못합니다.","본점 또는 주사무소 소재지가 납세지이고 지점은 될 수 없다":"사업자 단위 과세에서는 본점이나 주사무소가 납세지이고 지점은 납세지가 될 수 없습니다.","부가가치세·개별소비세·주세·교통·에너지·환경세는 신고로 확정되고, 인지세는 성립과 동시에 특별한 절차 없이 확정된다":"부가가치세 등은 납세자의 신고로 세액이 확정되지만 인지세는 성립과 동시에 별도 절차 없이 확정됩니다.","부가가치세를 별도로 적은 세금계산서를 발급하면 영세율을 적용하지 않는다":"수출재화 임가공용역은 부가가치세를 따로 적은 세금계산서를 내주면 영세율을 쓸 수 없습니다.","부과할 수 있는 날부터 5년이고, 무신고는 7년, 부정행위로 포탈하거나 환급·공제받으면 10년이다":"부과제척기간은 기본 5년이고 무신고는 7년, 부정행위로 포탈·환급·공제받으면 10년으로 길어집니다.","부동산 등기부상 소재지가 원칙이지만 부동산상의 권리만 대여하거나 국가·지방자치단체가 임대하면 업무총괄 장소다":"부동산임대업의 사업장은 등기부상 소재지이나 권리만 빌려주거나 국가 임대는 업무총괄 장소로 정합니다.","비거주자·외국법인의 국제운송은 여객이 탑승하거나 화물이 적재되는 장소":"비거주자·외국법인의 국제운송은 승객이 타거나 화물을 싣는 곳이 공급장소입니다.","사기나 그 밖의 부정한 행위로 조세를 포탈하거나 환급·공제를 받으면 2년 이하의 징역 또는 포탈세액등의 2배 이하 벌금이다":"조세포탈죄는 사기 등 부정한 행위로 세금을 면하거나 환급·공제받는 죄이며 2년 이하 징역 또는 포탈세액등의 2배 이하 벌금입니다.","사실상 사업을 계속하면 납세의무가 있다":"청산 중인 법인도 실제로 사업을 이어 가면 사업자로서 부가가치세를 부담합니다.","사업 개시일부터, 개시일 전에 등록을 신청했으면 신청한 날부터 과세기간이 시작한다":"신규사업자의 과세기간은 사업을 시작한 날, 시작 전에 등록했다면 신청한 날에 열립니다.","사업 개시일부터 20일 이내에 사업장 관할 세무서장에게 신청한다":"사업자등록은 사업을 시작한 날부터 20일 안에 사업장 관할 세무서장에게 신청해야 합니다.","사업 개시일부터 등록 신청일의 직전일까지 공급가액의 1퍼센트이다":"등록을 미룬 기간의 공급가액에 1퍼센트를 물리는 미등록 가산세는 개시일부터 신청 직전일까지 셉니다.","사업자인지와 관계없이 납세의무가 있다":"재화를 수입하는 자는 사업자가 아닌 개인이라도 수입 단계에서 부가가치세를 내야 합니다.","사업장이 둘 이상이면 본점 또는 주사무소 관할 세무서장에게 사업자 단위로 등록할 수 있고 등록번호는 하나다":"사업자 단위 과세를 택하면 본점 관할 세무서장에게 등록번호 하나로 모든 사업장을 묶어 처리합니다.","상호주의에 따라 적용하고, 첨부서류를 내지 않은 부분은 예정·확정신고로 보지 않는다":"비거주자·외국법인에는 상대국도 같은 혜택을 줄 때 영세율을 적용하며 서류를 안 내면 신고로 인정하지 않습니다.","섭씨 15도에서 전체용량 100분 중 알코올분의 용량이다":"알코올분 도수는 섭씨 15도에서 전체 부피 100 가운데 알코올이 차지하는 부피로 잽니다.","세관장에게 수입신고를 하면 과세표준을 신고한 것으로 보고 납부는 관세법에 따른다":"보세구역 반출자는 수입신고만으로 과세표준을 신고한 것으로 보고 납부는 관세법을 따릅니다.","세금계산서 미수취·필요적 기재사항 누락, 사업과 직접 관련 없는 지출, 개별소비세법상 자동차의 구입·임차·유지(운수업·자동차판매·임대·운전학원 등 영업용 제외), 기업업무추진비, 면세사업 관련, 토지 관련(형질변경·부지조성·건물 철거비 포함), 등록 전 매입세액":"세금계산서를 안 받았거나 사업과 무관한 지출, 일부 자동차 비용, 토지 관련 비용 등은 매입세액 공제에서 빠집니다.","세금이 붙은 원재료를 과세물품 제조에 쓰면 그 세액을 공제하고, 수출·군납, 제조장 환입, 의료용 등 원료 사용이면 환급한다":"세금이 이미 붙은 원재료를 과세물품 제조에 쓰면 그 세액을 공제하고 수출·환입 등이면 환급합니다.","수입 시에는 공관의 공용품, 주한외교관의 자가 소비용 수입, 외국에서 종교단체에 기증한 의식용 주류, 관세가 면제되는 여행자 휴대 주류, 품질불량으로 다시 들어온 수출 주류가 면세다":"수입 시 면세는 공관의 공용품, 외교관 자가 소비용, 외국에서 종교단체에 기증한 의식용 주류, 휴대 주류 등입니다.","수입신고 수리 전에 보세구역에서 반출하려면 세액 상당 담보를 제공한다":"수리 전에 보세구역에서 반출하려는 사람은 세액에 해당하는 담보를 제공해야 합니다.","수입신고 수리 전에 세관장의 승인을 받는다":"수입신고 수리 전에 보세구역에서 반출하려면 세관장의 승인을 받아야 합니다.","수입하는 자는 관할 세관장에게 납부한다":"수입 주류의 주세는 관할 세관장에게 납부합니다.","수출, 국외 제공 용역, 선박·항공기의 외국항행용역(상업서류 송달용역 포함), 내국신용장·구매확인서에 의한 공급(금지금 제외), 국내사업장 없는 외국법인에 대한 일정 용역으로서 외국환은행에서 원화로 받는 것, 외교공관에 대한 공급, 외국인 관광객 관광알선용역":"영세율은 수출, 외국항행용역, 내국신용장에 의한 공급 등 외화를 벌거나 국외 소비되는 거래에 적용합니다.","수출, 우리나라 주둔 외국군대 납품, 외국에 주둔하는 국군부대 납품, 주한외국공관 납품, 외국 선원 휴게소(안에서 음용하는 것) 납품, 검사 목적 수거, 무형유산 기능보유자가 무형유산 공개에 쓰는 주류, 의약품 원료, 연료용 등 공업용 주정은 면세다":"면세 주류는 수출, 주둔 외국군·국군 납품, 외국공관 납품, 의약품 원료, 공업용 주정 등입니다.","수출과 주한외국군 납품은 면세하고, 주한외국군 면세 물품을 양도하면 양수자에게서 징수한다":"수출과 주한외국군 납품은 면세하되 주한외국군의 면세 물품을 넘기면 받은 사람에게서 징수합니다.","수출과 주한외국군 납품은 수출 및 군납 면세다":"수출과 주한외국군 납품은 그 거래 자체가 면세 사유이므로 수출 및 군납 면세로 구분합니다.","수출 물품의 용기로 재수입하는 것, 외국 자선·구호기관에 기증하는 물품, 조난 해체재와 장비품, 외국 박람회 출품용 반출, 군함·재외공관에서 송부되는 공용품, 상업용 견본·광고용품, 입국자 휴대품, 거주자가 받는 소액물품은 무조건 면세다":"수출 용기의 재수입, 외국 구호기관 기증, 입국자 휴대품, 소액물품 등은 용도 조건 없이 무조건 면세합니다.","수출신고 수리일부터 6개월 내에 재수입되는 물품으로 원재료에 면제·환급·공제를 받은 사실이 없다고 관할 세무서장이 증명하는 것도 같다":"수출 후 6개월 내 재수입되는 물품은 원재료에 면제·환급·공제를 받은 사실이 없다고 증명되면 같은 무조건 면세입니다.","수출신고 수리 후 선적되지 않은 물품을 보세구역에서 반입하는 것은 수입이 아니고, 보세구역에는 자유무역지역이 포함된다":"수출 수리를 마치고 선적되지 않은 물품을 보세구역에서 들여오는 것은 수입이 아니며 자유무역지역도 보세구역입니다.","수출할 물품을 다른 장소로 반출, 과세물품 원료로 쓰기 위한 다른 제조장 반출, 위탁 공임만 받고 제조한 물품의 위탁자 창고 반출, 판매장·제조장 이전, 규격 검사용 반출, 박람회 출품 물품의 환입·반출, 내국신용장(제2차 포함)에 의한 수출업자 반출, 승용자동차의 30일 이상 판매장 전시 반출은 개별소비세를 징수하지 않는다":"수출, 원료 이동, 위탁 제조, 검사, 박람회 출품, 내국신용장 수출 등은 개별소비세를 걷지 않는 미납세반출입니다.","수출할 물품을 다른 장소로 반출, 위탁 공임만 받고 제조한 물품을 위탁자 창고로 반출, 규격검사용 반출·환입, 품질불량으로 제조장에 반환하는 것은 승인을 받으면 징수하지 않는다":"수출, 위탁 제조품의 위탁자 창고 반출, 규격검사, 품질불량 반환은 승인을 받으면 미납세반출로 징수하지 않습니다.","수탁자 명의로 공급하면 수탁자가, 위탁자 명의로 공급하면 위탁자가 납세의무를 진다":"신탁재산 관련 재화는 공급 명의에 따라 수탁자 또는 위탁자가 납세의무자가 됩니다.","신고된 하치장과 박람회 임시사업장, 제품 포장·충전만 하는 장소는 사업장이 아니다":"하치장, 박람회 임시사업장, 포장·충전만 하는 곳은 거래가 이루어지지 않아 사업장이 아닙니다.","신고 세액은 법정 신고납부기한의 다음 날, 고지 세액은 고지에 따른 납부기한의 다음 날부터 행사할 수 있다":"소멸시효는 신고 세액은 법정 신고납부기한 다음 날, 고지 세액은 고지의 납부기한 다음 날부터 진행합니다.","신용카드 가입 신청서 같은 계속적·반복적 거래 증서를 보완하는 문서":"신용카드 가입 신청서처럼 계속적·반복적 거래 증서를 보완하는 문서는 보완문서에서 제외됩니다.","실지귀속에 따르고, 구분할 수 없는 공통매입세액만 당기 공급가액 비율로 안분한다":"겸영사업자는 과세·면세 어느 쪽에 쓰였는지 아는 매입세액은 그대로 나누고 공통매입세액만 비율로 안분합니다.","알코올분 1도 이상의 음료이다":"주세법에서 주류는 알코올분이 1도 이상인 음료를 말합니다.","약사법상 의약품으로서 알코올분 6도 미만인 것":"약사법상 의약품이면서 알코올분이 6도 미만이면 마시는 술로 보지 않아 주류에서 제외됩니다.","업무총괄 장소 외에 추가 등록할 수 없다":"무인자동판매기 사업은 사업장이 따로 없으므로 업무총괄 장소 외에 추가로 등록하지 못합니다.","역무가 제공되거나 시설물·권리가 사용되는 장소다":"용역의 공급장소는 일을 해 주는 곳이거나 시설물·권리를 쓰는 곳입니다.","역무 제공과 시설물·권리 등 재화를 사용하게 하는 것이다":"용역의 공급은 일을 해 주는 것과 시설물·권리 등 재화를 쓰게 해 주는 것입니다.","영리든 비영리든 관계없이 사업상 독립적으로 재화·용역을 공급하는 자이고, 국가·지방자치단체·지방자치단체조합과 법인격 없는 사단·재단도 포함된다":"부가가치세법의 사업자는 영리 목적이 없어도 독립적으로 재화·용역을 공급하면 해당하며 국가도 들어갑니다.","영세율 대상인 면세 재화와 학술연구단체의 실비·무상 공급은 면세포기를 신고할 수 있다":"영세율 대상이거나 학술연구단체가 실비로 공급하는 재화는 면세를 포기하고 과세를 택할 수 있습니다.","예정신고는 예정신고기간이 끝난 후 25일 이내, 확정신고는 과세기간 종료 후 25일 이내에 하고 예정신고에는 가산세를 적용하지 않는다":"예정신고와 확정신고는 각 기간이 끝나고 25일 이내이며 예정신고에는 가산세를 매기지 않습니다.","외국에서 도착해 수입신고 수리 전인 물품과 외국 선박이 공해에서 잡은 수산물을 국내에 반입하면 재화의 수입이다":"수입신고 수리 전의 외국 도착 물품이나 외국 선박이 공해에서 잡은 수산물을 들여오면 재화의 수입입니다.","외국인전용판매장 면세 물품을 출국 때 소지하지 않거나 구입할 수 없는 자가 소지하면 개별소비세를 징수하고, 판매장을 대여하면 지정을 취소할 수 있다":"외국인전용판매장 면세품을 출국 때 소지하지 않거나 사지 못하는 자가 갖고 있으면 개별소비세를 징수합니다.","외국 자선단체·국가·지방자치단체에 기증하는 것은 무조건 면세다":"외국 자선단체나 국가·지방자치단체에 기증하는 물품은 용도 조건 없이 무조건 면세입니다.","위탁자 또는 본인이 공급한 것으로 보고, 위탁자·본인을 알 수 없을 때만 수탁자·대리인이 공급한 것으로 본다":"위탁매매는 원칙적으로 위탁자가 공급한 것으로 보고 위탁자를 모를 때만 수탁자를 공급자로 봅니다.","위탁자에게 이전하거나 수탁자가 바뀌어 이전하는 것은 재화의 공급이 아니다":"신탁이 끝나 위탁자에게 돌려주거나 수탁자를 바꾸며 넘기는 것은 대가를 받는 공급이 아닙니다.","이를 알선·중개한 자도 같으며 세무사·공인회계사·변호사가 알선하면 2분의 1을 가중한다":"가공거래의 알선·중개자도 거래 당사자와 같은 처벌 대상이며 전문 자격사가 하면 2분의 1을 더 무겁게 처벌합니다.","이의신청·심사청구·심판청구는 처분이 있음을 안 날부터 90일 이내에 하고, 이의신청은 30일 이내에 결정한다":"불복은 처분을 안 날부터 90일 이내에 하며 이의신청에 대해서는 30일 이내에 결정합니다.","이중장부 등 거짓 기장, 거짓 증빙, 장부 파기, 재산 은닉과 거래 조작, 고의적 장부 미작성, 세금계산서 조작 등 부과·징수를 불가능하게 하거나 현저히 곤란하게 하는 적극적 행위다":"부정한 행위는 이중장부, 거짓 증빙, 재산 은닉처럼 조세 부과·징수를 불가능하거나 매우 어렵게 만드는 적극적 행위입니다.","이화학 실험연구용·공업용 보석, 외국에서 학술연구·교육·자선 목적으로 기증되는 물품, 재수출할 물품으로 관세가 면제되는 것, 외국 무역선·원양어선에서 쓸 연료 외 소모품, 의료용·비료·석유화학공업용 원료 석유류, 산업용·발전용 유연탄, 여객자동차운송사업용 승용자동차는 용도를 지키는 조건으로 면제한다":"조건부 면세는 연구용 보석, 기증 물품, 재수출 물품, 원료 석유류, 유연탄 등을 정해진 용도로 쓰는 조건으로 면제합니다.","인도되거나 이용 가능하게 되는 때":"현금·외상판매의 공급시기는 재화가 인도되거나 이용할 수 있게 되는 때입니다.","인지세 납세의무는 과세문서를 작성한 때 성립하고 특별한 절차 없이 그 때 확정된다":"인지세는 과세문서를 만든 때 납세의무가 성립하고 별도 절차 없이 곧바로 확정됩니다.","일반과세자와 간이과세자로 나뉜다":"과세사업자는 일반과세자와 간이과세자 두 종류로 구분합니다.","일반 환급은 확정신고기한 후 30일 이내, 영세율·사업설비 취득·재무구조개선계획 이행 중인 조기환급은 신고기한 후 15일 이내에 한다":"환급은 일반 환급이 확정신고기한 후 30일 이내, 영세율 등 조기환급이 15일 이내에 이루어집니다.","일정 반출 수량 이하에 대해 100분의 50 범위에서 경감한다":"전통주는 일정 반출 수량 이하분에 한해 100분의 50 범위에서 세금을 덜어 줍니다.","있으면 처음 반출가격을 쓴다":"반출 후 되돌려 주는 금액이 있어도 과세표준은 처음 반출가격으로 계산합니다.","자기가 공급한 재화·용역의 시가":"금전 외의 대가를 받으면 자기가 공급한 재화·용역의 시가를 공급가액으로 삼습니다.","자선·구호기관에 기증되는 것, 재수출 조건 물품, 의료용·비료·농약·석유화학 원료와 외국항행선박·원양어선·항공기용은 조건부 면세이다":"자선·구호기관 기증, 재수출 조건, 의료용·비료·농약·석유화학 원료, 외국항행용은 용도 조건을 지켜야 하는 조건부 면세입니다.","작업복·작업모·작업화 제공, 견본품의 무상 인도, 특별재난지역 증여, 주된 거래 대가에 포함된 고객 증여":"작업복 제공이나 견본품의 무상 인도 등은 거래 목적이 달라 재화의 공급으로 간주하지 않습니다.","장애인 승용자동차는 1명당 1대, 500만원을 한도로 하고, 18세 미만 자녀 3명 이상 양육자의 승용자동차는 300만원을 한도로 한다":"장애인 승용자동차는 1명당 1대에 500만원, 18세 미만 3명 이상 양육자는 300만원이 한도입니다.","재산 가치가 있는 물건과 권리이고, 전기·가스·열 등 관리할 수 있는 자연력도 재산 가치가 있어야 재화다":"재화는 유체물과 권리를 말하며 전기·가스 같은 자연력도 재산 가치가 있어야 포함됩니다.","재원 조달과 수급상 필요하면 100분의 30 범위에서 대통령령으로 조정할 수 있다":"재원 조달이나 수급 사정에 따라 100분의 30 범위에서 대통령령으로 세율을 조정합니다.","재화 외에 재산 가치가 있는 모든 역무와 행위다":"용역은 물건이 아닌 일이나 서비스로서 재산 가치가 있는 모든 역무와 행위를 가리킵니다.","재화·용역의 공급 없이 세금계산서를 발급하거나 발급받는 가공거래는 3년 이하의 징역 또는 3배 이하 벌금이다":"실제 공급 없이 세금계산서를 주고받는 가공거래는 3년 이하 징역 또는 3배 이하 벌금으로 더 무겁게 처벌합니다.","재화의 이동이 필요하면 이동이 개시되는 장소, 필요 없으면 공급시기에 재화가 있는 장소다":"재화의 공급장소는 이동이 필요하면 출발하는 곳, 이동이 필요 없으면 공급시기에 재화가 있는 곳입니다.","적용받을 과세기간 개시 20일 전까지 신청한다":"사업자 단위 과세로 바꾸려면 적용받을 과세기간이 시작되기 20일 전까지 신청해야 합니다.","정부가 부과하는 조세는 결정 후 납부기한이 지난 때, 그 밖의 조세는 신고·납부기한이 지난 때 기수가 된다":"조세포탈의 기수 시기는 부과 조세는 결정 후 납부기한이 지난 때, 신고 조세는 신고·납부기한이 지난 때입니다.","정제하면 음용할 수 있는 조주정도 포함되며, 주정은 발효주류가 아니다":"조주정은 정제하면 마실 수 있어 주정에 포함되고 주정은 발효 과정을 거친 발효주류와 구별됩니다.","제조 물품은 제조장에서 반출할 때, 보세구역 반출 물품은 수입신고를 할 때, 입장·유흥음식·영업행위는 그 행위를 할 때 과세한다":"과세시기는 제조 물품은 반출할 때, 수입 물품은 수입신고 때, 입장·유흥음식·영업행위는 그 행위를 할 때입니다.","제조업 중소기업·개인은 104분의 4, 그 밖의 법인은 102분의 2, 법인 음식점은 106분의 6이다":"면세농산물을 쓰는 업종마다 공제율이 달라 제조업 중소기업·개인은 104분의 4, 법인 음식점은 106분의 6입니다.","제조원가에 10퍼센트 이윤을 더한다":"무상으로 내보내 통상가격을 알 수 없을 때는 제조원가에 10퍼센트 이윤을 더해 가격을 정합니다.","제조자로 보고 반입지 관할 세무서장에게 반입 사실을 신고한다":"위탁 제조 물품을 들여온 위탁자는 제조자로 간주해 반입지 관할 세무서장에게 신고합니다.","제조자로 보며 반입한 날이 속하는 달의 다음 달 15일까지 반입 사실을 신고한다":"반입한 자는 제조자로 간주하며 반입한 날이 속한 달의 다음 달 15일까지 반입 사실을 신고합니다.","제조장 밖에서 판매 목적으로 가치를 높이는 첨가 등 가공을 하면 제조로 본다":"제조장 밖에서 판매 목적으로 첨가 등 가공해 가치를 높이면 제조한 것으로 취급합니다.","제조장 반출 물품과 과세장소 입장행위는 매 분기 다음 달 25일까지(유류·담배는 매월, 다음 달 말일), 유흥음식행위는 매월 다음 달 25일까지, 카지노 영업행위는 다음 해 3월 31일까지 신고한다":"신고기한은 제조장 반출·입장행위가 분기 다음 달 25일, 유흥음식행위가 매월, 카지노가 다음 해 3월 31일입니다.","제조장 안에서 사용·소비되거나, 공매·경매·파산절차로 환가되거나, 제조를 사실상 폐지했을 때 남아 있는 물품은 반출로 본다":"제조장 안 소비, 공매·경매·파산 환가, 제조 폐지 때 남은 물품은 실제 반출이 없어도 반출로 봅니다.","제조장에서 마시거나, 부가가치세법상 재화의 공급으로 보거나, 공매·경매·파산절차로 환가되면 반출한 것으로 본다":"제조장에서 마시거나 재화의 공급으로 보는 경우, 공매·경매·파산 환가 때는 실제 반출이 없어도 반출로 봅니다.","제조장에서 반출하거나 수입신고를 하는 때 과세한다":"과세시기는 제조장에서 반출하거나 수입신고를 하는 때입니다.","제조장에서 반출하거나 판매장에서 판매하는 때, 과세장소 입장·유흥음식행위·영업행위를 하는 때 성립하고, 수입물품은 수입신고를 하는 때 성립한다":"개별소비세·주세는 제조장 반출, 판매장 판매, 과세행위 시 성립하며 수입물품은 수입신고 때 성립합니다.","제조장에서 사용·소비되거나 공매·경매·파산절차로 환가되면 반출로 본다":"제조장 안에서 써 버리거나 공매·경매·파산 절차로 환가되면 실제 반출이 없어도 반출로 칩니다.","제조·판매로 포탈하면 5년 이하의 징역 또는 포탈세액의 5배 이하 벌금":"가짜석유제품을 제조·판매해 세금을 포탈하면 5년 이하 징역 또는 포탈세액의 5배 이하 벌금입니다.","조건이 성취되거나 기한이 지나 확정되는 때":"조건부·기한부 판매는 조건이 이루어지거나 기한이 지나 거래가 확정되는 때가 공급시기입니다.","조세범 처벌법 위반은 국세청장, 지방국세청장 또는 세무서장의 고발이 없으면 검사가 공소를 제기할 수 없다":"조세범 처벌법 위반은 국세청장·지방국세청장·세무서장의 고발이 있어야 검사가 기소할 수 있습니다.","조세범 처벌법의 조세는 관세를 제외한 국세다":"조세범 처벌법에서 조세는 관세를 뺀 국세를 말합니다.","종이문서용 전자수입인지를 과세문서에 첨부해 내거나 세액을 납부하고 납부 사실을 표시하는 방법으로 낸다":"인지세는 전자수입인지를 문서에 붙이거나 세액을 납부하고 그 사실을 표시하는 방법으로 냅니다.","주된 공급에 통상 포함되는 부수 재화·용역은 주된 공급에 포함되고, 우연히·일시적으로 공급되거나 필연적으로 생기는 재화는 별도 공급이되 과세·면세 여부는 주된 사업을 따른다":"부수 공급은 주된 공급에 따라 붙어 함께 과세되며 우연히 생긴 재화는 따로 공급하되 과세 여부는 주된 사업을 따릅니다.","주세액을 넣지 않고 용기 대금과 포장비용을 넣되, 특별 제조 도자기병과 그 포장물, 전자인식표의 가격은 넣지 않는다":"반출 가격에는 주세액을 빼고 용기 대금과 포장비를 넣되 특별 도자기병과 전자인식표 가격은 넣지 않습니다.","주요자재의 전부 또는 일부를 부담하고 가공해 새 재화를 만들어 인도하면 재화의 공급이다":"가공을 맡을 때 주요자재를 일부라도 대고 새 재화를 만들어 넘기면 용역이 아니라 재화의 공급입니다.","주정, 발효주류, 증류주류, 기타 주류로 나뉜다":"주류는 주정, 발효주류, 증류주류, 기타 주류 네 가지로 구분합니다.","주한외교공관과 외교관의 자동차에 쓰는 물품은 상호주의에 따라 면세하고 연도별 면세한도량은 외교부장관이 정한다":"외교공관과 외교관의 자동차 용품은 상대국의 대우를 따르는 상호주의 방식이며 한도량은 외교부장관이 정합니다.","직전 과세기간의 과세공급가액 비율로 과세표준을 정한다":"공통사용 재화를 팔 때는 과세사업과 면세사업을 나누는 근거로 직전 과세기간 과세공급가액 비율을 씁니다.","직전 연도 공급대가가 1억400만원에 미달하는 개인사업자다":"간이과세자는 직전 연도 공급대가가 기준 금액인 1억400만원에 못 미치는 개인사업자입니다.","질권·저당권·양도담보 목적의 제공, 민사집행법상 경매, 국세징수법상 공매, 수용 대가 수령, 사업용 자산 물납, 조달청 창고증권 양도로서 임치물 반환이 없는 것, 신탁 종료나 수탁자 변경에 따른 이전":"담보 제공, 경매, 공매, 수용 보상금 수령 같은 것은 대가를 받아도 재화의 공급으로 보지 않습니다.","징역과 벌금을 병과할 수 있고, 상습범은 형의 2분의 1을 가중하며 법정신고기한 후 2년 이내 수정신고나 6개월 이내 기한 후 신고를 하면 감경할 수 있다":"징역과 벌금은 함께 줄 수 있고 상습범은 형의 2분의 1을 늘리며 수정신고나 기한 후 신고를 하면 깎아 줄 수 있습니다.","첨부한 전자수입인지를 재사용하면 조세범 처벌법에 따라 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다":"이미 쓴 전자수입인지를 다시 쓰면 조세범 처벌법에 따라 2년 이하 징역이나 2천만원 이하 벌금입니다.","청구시기와 지급시기 사이가 30일 이내이거나 공급시기가 같은 과세기간에 오면 7일이 지나 받아도 발급일이 공급시기다":"청구시기와 지급시기 간격이 짧거나 같은 과세기간 안이면 대가를 늦게 받아도 발급일을 공급시기로 삼습니다.","취득가액에 건물·구축물은 1과세기간마다 5%, 그 밖에는 25%씩 줄인 금액이다":"감가상각자산은 취득가액에서 건물·구축물은 1과세기간마다 5%, 그 밖은 25%씩 줄인 금액이 공급가액입니다.","특성, 주된 용도 순으로 판정하고 그래도 불분명하면 높은 세율 물품으로 본다":"과세물품이 둘 이상에 해당하면 특성, 주된 용도 순으로 판단하고 불분명하면 세율이 높은 쪽으로 봅니다.","특정 물품, 특정 장소 입장행위, 유흥음식행위, 영업행위에 부과한다":"개별소비세는 특정 물품, 입장행위, 유흥음식행위, 영업행위처럼 사치성 소비에 부과합니다.","포기하면 신고일부터 3년간 면세를 받지 못하며 이후 면세적용신고서를 낸다":"면세를 포기하면 신고일부터 3년 동안 다시 면세를 받지 못하고 이후에야 면세적용신고서를 냅니다.","포탈세액등이 3억원 이상이면서 납부할 세액의 100분의 30 이상이거나 5억원 이상이면 3년 이하의 징역 또는 3배 이하 벌금이다":"포탈 규모가 크면 가중 처벌하는데 3억원 이상이면서 100분의 30 이상이거나 5억원 이상이면 형이 올라갑니다.","포탈 우려나 휴업·폐업 때는 수시부과하고, 납세보전 명령 위반은 2천만원 이하 과태료다":"포탈 우려나 휴업·폐업이 있으면 수시부과하며 납세보전 명령을 어기면 2천만원 이하 과태료입니다.","필요적 기재사항은 공급자 등록번호·성명, 공급받는 자 등록번호, 공급가액과 세액, 작성연월일이고 단가·수량·공급연월일은 임의적 기재사항이다":"세금계산서에는 공급자·공급받는 자 등록번호, 공급가액과 세액, 작성연월일이 반드시 있어야 합니다.","하나의 문서 내용을 다른 문서가 보완해 하나의 계약을 이루면 그 보완문서도 과세문서로 본다":"보완문서 규정은 두 문서가 합쳐져 하나의 계약이 되는 경우 보충하는 쪽 문서에도 인지세를 과세한다는 뜻입니다.","하지 않았어도 납세의무는 생긴다":"사업자등록이나 거래징수를 빠뜨려도 공급 사실이 있으면 납세의무는 사라지지 않습니다.","현물과 교환되어 실제 인도되는 때":"상품권은 팔 때가 아니라 현물과 바꾸어 실제로 인도되는 때가 공급시기입니다.","휘발유와 유사 대체유류(리터당 475원), 경유와 유사 대체유류(리터당 340원) 두 가지다":"과세물품은 휘발유와 경유 두 가지이며 유사 대체유류도 각각 포함하고 세율은 리터당 475원, 340원입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
